/* Считаем количество карточек, которые были разработаны John Avon и у которых версионная версия (foil) не является мощной (powerball). */
SELECT COUNT(*) 
FROM cards AS T1 
JOIN rulings AS T2 ON T1.uuid = T2.uuid 
WHERE T1.artist LIKE '%John Avon%' AND T2.text NOT LIKE '%powerball%';

SELECT DISTINCT keywords 
FROM cards 
WHERE name = 'Angel of Mercy';

SELECT "convertedmanacost" 
FROM "cards" 
